export function normalizeRaids(raw={}){return {partner:typeof raw?.partner==='string'?raw.partner:'',encounter:raw?.encounter&&typeof raw.encounter.id==='string'&&/^\d+$/.test(raw.encounter.key)?{id:raw.encounter.id,key:raw.encounter.key}:null,claims:raw?.claims&&typeof raw.claims==='object'&&!Array.isArray(raw.claims)?raw.claims:{},completed:Math.max(0,Math.floor(+raw?.completed||0)),wins:Math.max(0,Math.floor(+raw?.wins||0)),shinies:Math.max(0,Math.floor(+raw?.shinies||0))}}
